mapper.delete:
update bm_procedure_step_model
set is_deleted = 1,
del_id_flag = id
where procedure_model_id = #{procedureModelId}

    and id not in

        #{item}

mapper.select:
SELECT t1.record_version_id as recordVersionId, t1.record_item_id as recordItemId, t1.procedure_model_id AS procedureModelId, t1.node_function as nodeFunction, t1.name as name, t2.`name` as procedureName FROM bm_procedure_step_model as t1 join bm_procedure_model as t2 on t1.procedure_model_id = t2.id WHERE t1.is_deleted = 0 AND t1.del_id_flag = 0 and t2.is_deleted = 0 and t2.del_id_flag = 0 and t1.process_id =#{processId} and t1.process_version =#{processVersion} and t1.procedure_model_id in
#{item}
order by t2.sort asc

select t1.id as id, t1.node_id as nodeId, t1.process_id as processId, t1.node_function as nodeFunction, t1.reusable as reusable, t1.procedure_id as procedureId, t1.procedure_model_id as procedureModelId, t1.procedure_step_id as procedureStepId, t1.process_version as processVersion, t1.record_version_id, t1.name as name from bm_procedure_step_model t1
t1.is_deleted = 0 AND
t1.process_id = #{qeuryDTO.processId} and t1.process_version = #{qeuryDTO.processVersion} and t1.record_item_id = #{qeuryDTO.recordId} and t1.reusable = #{qeuryDTO.reuse}
